def ref(key,title,author,url,loc,year='',note='verified',detail=''):
    refs.append(dict(key='A_'+key,title=title,author=author,url=url,loc=loc,year=year,note=note,detail=detail))
def query(qid,engine,query,results,applies):
    searches.append(dict(search_id=qid,date=DATE,engine=engine,query=query,opened_results=results,exact_match_or_boundary=applies))
def claim(n,its,his,modern,status,cl,fate,fd,present,rr,check,comp='',confidence='high',locitem=None):
    ident=f'CL-SA03-{n:03}'
    pp=[byid[f'SA03-{i}'] for i in its]
    lp=pp if locitem is None else [byid[f'SA03-{locitem}']]
    ls=[]
    for p in lp:
        for l in p['lines']:
            if l not in ls:ls.append(l)
    claims.append(dict(id=ident,items=[p['id'] for p in pp],cote=91,scans=sorted(set(s for p in lp for s in p['scans'])),lines=ls,his_statement=his,statement=modern,status_on_pages=status,computation=comp or 'No numerical computation is used; see the stated proof check and source comparison.',**{'class':cl},fate=fate,fate_date=fd,present_status='As of 2026-11-19: '+present,refs=['A_'+r for r in rr],confidence=confidence))
    typ,out=check
    events.append(dict(statement_id=ident,date=DATE,who=WHO,type=typ,outcome=out))
def problem(n,title,its,asst,plaus,soa,why,worth,rr):
    problems.append(dict(id=f'MP-SA03-{n:02}',title=title,occurrences=[dict(item=f'SA03-{i}',scans=byid[f'SA03-{i}']['scans'],lines=byid[f'SA03-{i}']['lines']) for i in its],as_he_states=asst,plausible_today=plaus,state_of_art=soa,why_open=why,worth=worth,refs=['A_'+r for r in rr]))

